const ASSETS = {
  hero: '/images/monaco-panorama.jpg',
  nice: '/images/nice-real.jpg',
  monaco: '/images/monaco-panorama.jpg',
  france: '/images/france.jpg',
  boat: '/images/boat-real.jpg',
};
const money = (value) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value);
const initialTrip = { travelers: 1, stay: 'nice', race: 'grandstand', boat: false, boatGuests: 1, transfer: false };
function loadTrip() { try { const saved = JSON.parse(localStorage.getItem('guideless-trip') || '{}'); const travelers = Math.max(1, Math.min(4, Number(saved?.travelers) || 1)); return { ...initialTrip, travelers: Math.floor(travelers), stay: saved?.stay === 'monaco' ? 'monaco' : 'nice', race: ['none','grandstand','terrace','yacht'].includes(saved?.race) ? saved.race : 'grandstand', boat: saved?.boat === true, boatGuests: Math.max(1, Math.min(Math.floor(Number(saved?.boatGuests) || 1), Math.floor(travelers))), transfer: saved?.transfer === true }; } catch { return initialTrip; } }
function calculate(trip) {
  const base = 1890 * trip.travelers;
  const stay = (trip.stay === 'monaco' ? 3950 : 0) * trip.travelers;
  const race = ({ none: 0, grandstand: 1290, terrace: 3490, yacht: 5950 }[trip.race] || 0) * trip.travelers;
  const boat = trip.boat ? 210 * Math.min(trip.boatGuests, trip.travelers) : 0;
  const transfer = trip.transfer ? 120 : 0;
  return { base, stay, race, boat, transfer, total: base + stay + race + boat + transfer, today: 500 * trip.travelers + race + boat + transfer, later: base + stay - 500 * trip.travelers };
}
const raceNames = { none: 'Explore at your own pace', grandstand: 'Grandstand K', terrace: 'Harbour terrace', yacht: 'Harbour yacht' };

