function App() {
  const [route, setRoute] = useState(window.location.hash.replace('#', '').split('#')[0] || '/');
  const [trip, setTrip] = useState(loadTrip);
  useEffect(() => { try { localStorage.setItem('guideless-trip', JSON.stringify(trip)); } catch {} }, [trip]);
  useEffect(() => {
    const change = () => { const parts = window.location.hash.slice(1).split('#'); setRoute(parts[0] || '/'); if (parts[1]) setTimeout(() => document.getElementById(parts[1])?.scrollIntoView({ behavior: 'smooth' }), 80); else window.scrollTo(0, 0); };
    window.addEventListener('hashchange', change); change();
    return () => window.removeEventListener('hashchange', change);
  }, []);
  const navigate = (path, section) => { if (route === path && section) document.getElementById(section)?.scrollIntoView({ behavior: 'smooth' }); else window.location.hash = path + (section ? `#${section}` : ''); };
  useEffect(() => { document.title = ({ '/': 'Guideless — A little structure. A lot of freedom.', '/trip': 'The Monaco weekend — Guideless', '/france': 'A little more France — Guideless', '/approach': 'A design exploration for Guideless', '/build': 'Make Monaco yours — Guideless', '/app': 'Your trip companion — Guideless' })[route] || 'Guideless Travel'; }, [route]);
  return <><a className="skip-link" href="#main-content" onClick={e => { e.preventDefault(); document.getElementById('main-content')?.focus(); }}>Skip to content</a><Header route={route} navigate={navigate} /><div id="main-content" tabIndex={-1}>{route === '/approach' ? <Approach setTrip={setTrip} navigate={navigate} /> : route === '/trip' ? <TripPage navigate={navigate} /> : route === '/france' ? <TripPage navigate={navigate} france /> : route === '/build' ? <Builder trip={trip} setTrip={setTrip} navigate={navigate} /> : route === '/app' ? <Companion trip={trip} setTrip={setTrip} /> : <Home navigate={navigate} />}</div></>;
}

createRoot(document.getElementById('root')).render(<App />);
import './refinements.css';
